'use strict';

/**
 * middleware/upload.js
 * Profile picture uploads via Multer (disk storage).
 *
 * Security controls:
 *   * Only image MIME types are accepted, and they are verified by the file
 *     MAGIC BYTES (file-type sniffing) rather than trusting the client's
 *     Content-Type header alone.
 *   * A hard byte limit (default 2 MB) prevents disk exhaustion.
 *   * Exactly one file, under the single field name "avatar".
 *   * The stored filename is generated by the server from a random token plus
 *     a validated extension. The original filename is NEVER used, which blocks
 *     path traversal ("../../evil.exe") and overwriting existing files.
 *   * Files are written outside the web-served tree and only ever returned as
 *     static content from the dedicated /uploads route, which sets
 *     X-Content-Type-Options: nosniff so a served image cannot reclassify
 *     itself as HTML.
 */

const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const multer = require('multer');
const { env } = require('../config/env');
const { ApiError } = require('../utils/errors');

// Minimal magic-byte signatures for the formats we accept.
const SIGNATURES = [
  { ext: 'jpg', mime: 'image/jpeg', test: (b) => b[0] === 0xFF && b[1] === 0xD8 && b[2] === 0xFF },
  // PNG signature is exactly: 89 50 4E 47 0D 0A 1A 0A
  { ext: 'png', mime: 'image/png', test: (b) => b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4E && b[3] === 0x47 },
  { ext: 'gif', mime: 'image/gif', test: (b) => b.slice(0, 4).toString('latin1') === 'GIF8' },
  { ext: 'webp', mime: 'image/webp', test: (b) => b.slice(0, 4).toString('latin1') === 'RIFF' && b.slice(8, 12).toString('latin1') === 'WEBP' },
];

/**
 * Detect the real image type from the first bytes of the file.
 * @param {Buffer} buffer
 * @returns {{ext:string, mime:string}|null}
 */
function sniffImageType(buffer) {
  if (!buffer || buffer.length < 12) return null;
  for (const signature of SIGNATURES) {
    try {
      if (signature.test(buffer)) return { ext: signature.ext, mime: signature.mime };
    } catch (_) { /* ignore malformed buffer */ }
  }
  return null;
}

// Ensure the upload directory exists.
const uploadRoot = env.paths.uploads;
if (!fs.existsSync(uploadRoot)) {
  fs.mkdirSync(uploadRoot, { recursive: true });
}

const storage = multer.diskStorage({
  destination(_req, _file, cb) {
    cb(null, uploadRoot);
  },
  filename(req, file, cb) {
    // Server-controlled name: avatar-<userId>-<random>.<ext>
    const userId = req.user && req.user.id ? req.user.id : 'anon';
    const random = crypto.randomBytes(8).toString('hex');
    // The extension is chosen by the SERVER after sniffing, not by the client.
    cb(null, `pending-${userId}-${random}`);
  },
});

const upload = multer({
  storage,
  limits: {
    fileSize: env.upload.maxBytes,
    files: 1,
    fields: 5,
  },
  fileFilter(req, file, cb) {
    // Reject obviously wrong field names early.
    if (file.fieldname !== 'avatar') {
      return cb(ApiError.badRequest('Unexpected file field.', 'UPLOAD_FIELD'));
    }
    return cb(null, true);
  },
});

/**
 * Express middleware that accepts a single "avatar" image, verifies its real
 * type by magic bytes, renames it with the correct extension and attaches
 * req.uploadedFile = { filename, path, size, mime }.
 */
function requireImage(req, _res, next) {
  upload.single('avatar')(req, _res, (error) => {
    if (error) return next(error);

    if (!req.file) {
      return next(ApiError.badRequest('Please choose an image to upload.', 'NO_FILE'));
    }

    // Read the leading bytes and confirm it really is an image.
    let header;
    try {
      const fd = fs.openSync(req.file.path, 'r');
      header = Buffer.alloc(16);
      fs.readSync(fd, header, 0, 16, 0);
      fs.closeSync(fd);
    } catch (readError) {
      return next(ApiError.internal('Could not read the uploaded file.', 'UPLOAD_READ_FAILED'));
    }

    const detected = sniffImageType(header);
    if (!detected) {
      // Delete the rejected file immediately so nothing lingers on disk.
      fs.unlink(req.file.path, () => {});
      return next(ApiError.badRequest(
        'Only genuine JPEG, PNG, GIF or WebP images are allowed.',
        'INVALID_IMAGE_TYPE'
      ));
    }

    // Give it the correct extension and confirm the final size.
    const finalName = `${req.file.filename}.${detected.ext}`;
    const finalPath = path.join(uploadRoot, finalName);
    try {
      fs.renameSync(req.file.path, finalPath);
    } catch (renameError) {
      return next(ApiError.internal('Could not store the uploaded file.', 'UPLOAD_STORE_FAILED'));
    }

    req.uploadedFile = {
      filename: finalName,
      path: finalPath,
      size: req.file.size,
      mime: detected.mime,
    };
    return next();
  });
}

/** Delete a stored upload by filename, ignoring "not found". */
function deleteUpload(filename) {
  if (!filename || filename.includes('..') || filename.includes('/') || filename.includes('\\')) return;
  const target = path.join(uploadRoot, path.basename(filename));
  fs.unlink(target, () => {});
}

module.exports = { requireImage, deleteUpload, sniffImageType, uploadRoot };
